package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// lookupUser retrieves user profile by username
func lookupUser(w http.ResponseWriter, r *http.Request) {
	username := r.URL.Query().Get("user")
	if username == "" {
		http.Error(w, "missing user parameter", http.StatusBadRequest)
		return
	}

	// Basic length check
	if len(username) > 128 {
		http.Error(w, "username too long", http.StatusBadRequest)
		return
	}

	// Remove null bytes as a safety measure
	username = strings.ReplaceAll(username, "\x00", "")

	query := fmt.Sprintf("SELECT id, username, email, role FROM users WHERE username = '%s'", username)
	log.Printf("[AUDIT] query executed: %s", query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("[ERROR] query failed: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var uname, email, role string
		if err := rows.Scan(&id, &uname, &email, &role); err != nil {
			continue
		}
		results = append(results, fmt.Sprintf("%d|%s|%s|%s", id, uname, email, role))
	}

	if len(results) == 0 {
		http.Error(w, "user not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "text/plain")
	for _, line := range results {
		fmt.Fprintln(w, line)
	}
}

// healthCheck endpoint for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	fmt.Fprint(w, "ok")
}

// adminReset is an internal endpoint for cache invalidation
func adminReset(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Internal-Token")
	expected := os.Getenv("INTERNAL_TOKEN")
	if token != expected || expected == "" {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	// Reset connection pool
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
	fmt.Fprint(w, "reset complete")
}

func main() {
	http.HandleFunc("/api/user", lookupUser)
	http.HandleFunc("/health", healthCheck)
	http.HandleFunc("/internal/reset", adminReset)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
